#!/usr/bin/env python3
"""Merges the C that V generates on each OS and architecture into one file.

    scripts/amalgamation-merge.py DIR

DIR has the files from "scripts/amalgamation.sh generate" for one or more
platforms (vsql_OS_ARCH.c, libvsql_OS_ARCH.c, vsql_runtime_OS.c,
vsql_OS_ARCH.mk and the files they include), and gc.h from amalgamation/. It
writes DIR/vsql.c and DIR/libvsql.c, which build on every one of those
platforms without any other C file, and DIR/vsql.mk with the libraries and
linker options that each platform needs (see amalgamation/Makefile).

For each program and platform, the C is:

1. The defines from V's C compiler command (-D in vsql_OS_ARCH.mk).
2. The C that V links from outside of the generated C (vsql_runtime_OS.c: the
   Boehm garbage collector and V's helpers).
3. The generated C, without its own declarations of the garbage collector's
   functions (see without_gc_prototypes).

with every file that they include from DIR put in place of its #include, so
nothing else is needed to build it. The C for each platform is then merged into
one file, where the lines that aren't the same on every platform are inside
"#if defined(VSQL_LINUX) ..." (see HEADER).

The C is split into chunks that are a single line, or a whole #if ... #endif
(and a whole comment or multi-line directive), so that the #if around a chunk
can never come between an #if and its #endif. The chunks of each platform are
merged with diff, one platform at a time. The merged file is checked by taking
the lines for each platform back out of it, which have to be the same as the C
for that platform.
"""

import hashlib
import os
import re
import subprocess
import sys
import tempfile

OSES = ['dragonfly', 'freebsd', 'linux', 'macos', 'netbsd', 'openbsd', 'windows']
ARCHES = ['amd64', 'arm64']
OS_MACROS = {
    'dragonfly': 'VSQL_DRAGONFLY',
    'freebsd': 'VSQL_FREEBSD',
    'linux': 'VSQL_LINUX',
    'macos': 'VSQL_MACOS',
    'netbsd': 'VSQL_NETBSD',
    'openbsd': 'VSQL_OPENBSD',
    'windows': 'VSQL_WINDOWS',
}
ARCH_MACROS = {'amd64': 'VSQL_AMD64', 'arm64': 'VSQL_ARM64'}

# The merged file's own #if and #endif lines end with this, so that they can be
# told apart from the ones in the C when checking it.
MARK = '/* vsql platform */'

HEADER = '''\
// {program}.c is {description}, as C generated by V for each OS and
// architecture, merged into one file by scripts/amalgamation-merge.py. It
// needs no other C files, see Makefile for how to build it.
//
// V can generate one C file for every OS and architecture (-os cross), but
// that C has no garbage collector (https://github.com/vlang/v/issues/31421), so
// the C is generated on each OS and architecture instead, and the parts that
// are different are inside "#if defined(VSQL_LINUX)" and so on.
//
// It has the Boehm garbage collector (gc.c, see its license below) and helpers
// from V (see LICENSE-V).
#if defined(_WIN32)
#define VSQL_WINDOWS
#elif defined(__APPLE__)
#define VSQL_MACOS
#elif defined(__linux__)
#define VSQL_LINUX
#elif defined(__FreeBSD__)
#define VSQL_FREEBSD
#elif defined(__OpenBSD__)
#define VSQL_OPENBSD
#elif defined(__NetBSD__)
#define VSQL_NETBSD
#elif defined(__DragonFly__)
#define VSQL_DRAGONFLY
#endif

#if defined(__x86_64__) || defined(_M_X64)
#define VSQL_AMD64
#elif defined(__aarch64__) || defined(_M_ARM64)
#define VSQL_ARM64
#endif

#if !({supported})
#error "There is no generated C for this OS and architecture."
#endif

'''

# gc.c on macOS has its own semaphores (sem_t, sem_init, ...), since macOS
# doesn't have unnamed POSIX semaphores, and they clash with the ones from
# <semaphore.h> that the generated C includes. They're renamed while gc.c is
# compiled.
MACOS_SEMAPHORES = ['sem_t', 'sem_init', 'sem_post', 'sem_wait', 'sem_destroy']

# gc.c #undefs the thread functions that gc.h redirects to the collector
# (pthread_create to GC_pthread_create, ...), so it can call the real ones. V
# compiles gc.c on its own, but here the #undef would carry on to the rest of
# the C, and threads that V starts wouldn't be registered with the collector
# ("Collecting from unknown thread"). gc_pthread_redirects.h defines them again
# after gc.c, with GC_PTHREAD_REDIRECTS_ONLY so that it only has the #defines.
def gc_redirects(folder):
    header = os.path.join(folder, 'gc', 'gc_pthread_redirects.h')
    if not os.path.isfile(header):
        return []
    return ([
        '#if defined(GC_H) && defined(GC_PTHREADS)\n',
        '#undef GC_PTHREAD_REDIRECTS_H\n',
        '#define GC_PTHREAD_REDIRECTS_ONLY\n',
        '// #include "gc/gc_pthread_redirects.h"\n',
    ] + inline(folder, header, set()) + [
        '#undef GC_PTHREAD_REDIRECTS_ONLY\n',
        '#endif\n',
    ])


GC_PROTOTYPE = re.compile(r'^[A-Za-z_][\w ]*[\w*]\s*\b(GC_\w+)\(.*\);\s*$')
INCLUDE = re.compile(r'^\s*#\s*include\s*([<"])([^>"]+)[>"]')
DIRECTIVE = re.compile(r'^\s*#\s*(\w+)')


def main():
    if len(sys.argv) != 2:
        sys.exit(__doc__)
    folder = sys.argv[1]

    platforms = [(os_, arch) for os_ in OSES for arch in ARCHES
                 if os.path.exists(os.path.join(folder, f'vsql_{os_}_{arch}.c'))]
    if not platforms:
        sys.exit(f'there is no generated C in {folder}')

    flags = {p: read_flags(folder, *p) for p in platforms}
    for program, description in [
        ('vsql', 'the vsql command line program'),
        ('libvsql', 'libvsql, the SQL/CLI (ISO/IEC 9075-3) shared library (see libvsql.h)'),
    ]:
        sources = {}
        for p in platforms:
            sources[p] = platform_source(folder, program, p, flags[p][program][0])
        merged = merge(platforms, sources)
        supported = ' || '.join(f'(defined({OS_MACROS[o]}) && defined({ARCH_MACROS[a]}))'
                                for o, a in platforms)
        text = HEADER.format(program=program, description=description, supported=supported)
        text += merged
        check(merged, platforms, sources)
        with open(os.path.join(folder, f'{program}.c'), 'w', newline='\n') as f:
            f.write(text)

    with open(os.path.join(folder, 'vsql.mk'), 'w', newline='\n') as f:
        f.write('# Generated by scripts/amalgamation-merge.py from V\'s C compiler command.\n')
        for o, a in platforms:
            f.write(f'\nifeq ($(VSQL_OS)_$(VSQL_ARCH),{o}_{a})\n')
            f.write(f'VSQL_FLAGS = {" ".join(flags[(o, a)]["vsql"][1])}\n')
            f.write(f'LIBVSQL_FLAGS = {" ".join(flags[(o, a)]["libvsql"][1])}\n')
            f.write('endif\n')


def read_flags(folder, os_, arch):
    """Splits the flags in vsql_OS_ARCH.mk into the defines, which go in the C,
    and the rest (libraries and linker options), which go in vsql.mk."""
    flags = {}
    with open(os.path.join(folder, f'vsql_{os_}_{arch}.mk')) as f:
        for line in f:
            m = re.match(r'^(VSQL|LIBVSQL)_FLAGS =(.*)$', line.rstrip('\n'))
            if not m:
                continue
            defines, others = [], []
            for arg in m.group(2).split():
                if arg.startswith('-D'):
                    name, _, value = arg[2:].partition('=')
                    defines.append(f'#define {name} {value or 1}\n')
                else:
                    others.append(arg)
            flags[m.group(1).lower()] = (defines, others)
    return flags


def platform_source(folder, program, platform, defines):
    """The lines of C for one program on one platform."""
    os_, arch = platform
    once = set()
    runtime = inline(folder, os.path.join(folder, f'vsql_runtime_{os_}.c'), once,
                     after={'gc.c': gc_redirects(folder)})
    generated = inline(folder, os.path.join(folder, f'{program}_{os_}_{arch}.c'), once)
    lines = list(defines) + thread_stack_size(generated)
    if os_ == 'macos':
        lines += [f'#define {name} vsql_gc_{name}\n' for name in MACOS_SEMAPHORES]
    lines += runtime
    if os_ == 'macos':
        lines += [f'#undef {name}\n' for name in MACOS_SEMAPHORES]
    lines += without_gc_prototypes(generated, ''.join(runtime))
    return lines


def thread_stack_size(generated):
    """thread_helper.h (in the runtime) defines V_THREAD_STACK_SIZE as 0 if it
    isn't defined yet, which would stop the generated C from defining its own
    stack size for threads (pthread_attr_setstacksize fails with 0). So the
    generated C's value is defined before the runtime."""
    for line in generated:
        m = re.match(r'^\s*#\s*define\s+V_THREAD_STACK_SIZE\s+(\d+)\s*$', line)
        if m:
            return [f'#define V_THREAD_STACK_SIZE {m.group(1)}\n']
    return []


def without_gc_prototypes(lines, runtime):
    """V declares the garbage collector functions that it calls itself, such as
    "i32 GC_get_stack_base(void*);", rather than including gc.h, and some of
    them have different types to gc.h (which is in the same file now). They're
    commented out when gc.h declares the function, so the one from gc.h is
    used."""
    out = []
    for line in lines:
        m = GC_PROTOTYPE.match(line)
        if m and re.search(r'\bGC_API\b[^;]*?\b' + m.group(1) + r'\s*\(', runtime):
            line = f'// {line.rstrip()} (declared by gc.h)\n'
        out.append(line)
    return out


def inline(folder, path, once, after=None):
    """The lines of a file, with the files that it includes from the folder in
    place of their #include, like the C compiler does with "-I folder". A file
    with "#pragma once", or that's all inside an include guard, is only put in
    once (gc.h is included by most of the runtime). after has lines to put
    after an included file, by its name."""
    with open(path, encoding='utf-8', errors='surrogateescape', newline='') as f:
        text = f.read().replace('\r\n', '\n')
    lines = text.splitlines(keepends=True)
    if lines and not lines[-1].endswith('\n'):
        lines[-1] += '\n'
    if re.search(r'^\s*#\s*pragma\s+once\b', text, re.M) or include_guard(lines):
        key = os.path.realpath(path)
        if key in once:
            return []
        once.add(key)

    out = []
    for line in lines:
        m = INCLUDE.match(line)
        if m:
            candidates = [folder]
            if m.group(1) == '"':
                candidates.insert(0, os.path.dirname(path))
            found = None
            for d in candidates:
                candidate = os.path.normpath(os.path.join(d, m.group(2)))
                if os.path.isfile(candidate):
                    found = candidate
                    break
            if found:
                out.append(f'// {line.strip()}\n')
                out += inline(folder, found, once)
                out += (after or {}).get(m.group(2), [])
                continue
        out.append(line)
    return out


def include_guard(lines):
    """The name of the include guard that the whole file is inside, such as
    GC_H for "#ifndef GC_H", "#define GC_H", ..., "#endif", or None."""
    directives = []
    in_comment = False
    for line in lines:
        if not in_comment:
            m = DIRECTIVE.match(line)
            if m:
                directives.append((m.group(1), line))
            elif line.strip() and not line.strip().startswith(('/*', '//')):
                # Code outside of the guard.
                if not directives:
                    return None
        in_comment = scan(line, in_comment, directive=bool(DIRECTIVE.match(line)))
    if len(directives) < 3 or directives[0][0] != 'ifndef' or directives[1][0] != 'define':
        return None
    m = re.match(r'^\s*#\s*ifndef\s+(\w+)\s*$', directives[0][1])
    if not m or not re.match(r'^\s*#\s*define\s+' + m.group(1) + r'\b', directives[1][1]):
        return None
    # The #endif that matches the #ifndef has to be the last directive, and
    # there can't be any code after it.
    depth = 0
    for i, (name, _) in enumerate(directives):
        if name in ('if', 'ifdef', 'ifndef'):
            depth += 1
        elif name == 'endif':
            depth -= 1
            if depth == 0 and i != len(directives) - 1:
                return None
    last = max(i for i, line in enumerate(lines) if line == directives[-1][1])
    for line in lines[last + 1:]:
        if line.strip() and not line.strip().startswith(('/*', '//', '*')):
            return None
    return m.group(1)


def chunks(lines):
    """Splits the lines into chunks that each end outside of any #if, comment or
    multi-line directive, so they can be put inside an #if."""
    result = []
    current = []
    depth = 0
    in_comment = False
    continued = False
    for line in lines:
        current.append(line)
        if continued:
            # The rest of a directive that ends with a backslash.
            in_comment = scan(line, in_comment, directive=True)
            continued = line.rstrip('\n').endswith('\\')
        elif not in_comment and DIRECTIVE.match(line):
            name = DIRECTIVE.match(line).group(1)
            if name in ('if', 'ifdef', 'ifndef'):
                depth += 1
            elif name == 'endif':
                depth -= 1
                if depth < 0:
                    sys.exit(f'#endif without #if: {line!r}')
            in_comment = scan(line, in_comment, directive=True)
            continued = line.rstrip('\n').endswith('\\')
        else:
            in_comment = scan(line, in_comment)
        if depth == 0 and not in_comment and not continued:
            result.append(''.join(current))
            current = []
    if current:
        sys.exit('the C ends inside an #if, comment or directive')
    return result


def scan(line, in_comment, directive=False):
    """Whether a block comment is still open at the end of the line."""
    i = 0
    n = len(line)
    while i < n:
        if in_comment:
            end = line.find('*/', i)
            if end < 0:
                return True
            in_comment = False
            i = end + 2
            continue
        c = line[i]
        if c == '/' and line.startswith('/*', i):
            in_comment = True
            i += 2
        elif c == '/' and line.startswith('//', i):
            return False
        elif c in '"\'' and not (directive and c == "'"):
            # A string or character literal, which can't have a comment in
            # it. An apostrophe in a directive (such as #error) isn't one.
            i += 1
            while i < n and line[i] != c and line[i] != '\n':
                i += 2 if line[i] == '\\' else 1
            i += 1
        else:
            i += 1
    return in_comment


def merge(platforms, sources):
    """Merges the chunks of each platform, and returns the C with an #if
    around each run of chunks that aren't on every platform."""
    merged = None
    for p in platforms:
        items = chunks(sources[p])
        if merged is None:
            merged = [(c, {p}) for c in items]
            continue
        result = []
        i = j = 0
        for (a1, a2, b1, b2) in diff([c for c, _ in merged], items):
            # Matching chunks before the change are on this platform too.
            while i < a1:
                result.append((merged[i][0], merged[i][1] | {p}))
                i += 1
                j += 1
            result += merged[a1:a2]
            result += [(c, {p}) for c in items[b1:b2]]
            i, j = a2, b2
        while i < len(merged):
            result.append((merged[i][0], merged[i][1] | {p}))
            i += 1
            j += 1
        assert j == len(items)
        merged = result

    out = []
    everywhere = set(platforms)
    k = 0
    while k < len(merged):
        where = merged[k][1]
        start = k
        while k < len(merged) and merged[k][1] == where:
            k += 1
        text = ''.join(c for c, _ in merged[start:k])
        if where == everywhere:
            out.append(text)
        else:
            out.append(f'#if {condition(where, platforms)} {MARK}\n{text}#endif {MARK}\n')
    return ''.join(out)


def diff(a, b):
    """The changes from a to b, as (a_start, a_end, b_start, b_end), using the
    diff command (Python's difflib is too slow for this many lines)."""
    with tempfile.TemporaryDirectory() as tmp:
        paths = []
        for name, items in [('a', a), ('b', b)]:
            path = os.path.join(tmp, name)
            with open(path, 'w') as f:
                for c in items:
                    f.write(hashlib.sha1(c.encode('utf-8', 'surrogateescape')).hexdigest() + '\n')
            paths.append(path)
        out = subprocess.run(['diff', paths[0], paths[1]], capture_output=True, text=True)
        if out.returncode > 1:
            sys.exit(f'diff failed: {out.stderr}')

    changes = []
    for line in out.stdout.splitlines():
        m = re.match(r'^(\d+)(?:,(\d+))?([acd])(\d+)(?:,(\d+))?$', line)
        if not m:
            continue
        l1, l2, kind, r1, r2 = m.groups()
        l1, r1 = int(l1), int(r1)
        l2 = int(l2) if l2 else l1
        r2 = int(r2) if r2 else r1
        if kind == 'a':
            # After line l1 of a, add lines r1..r2 of b.
            changes.append((l1, l1, r1 - 1, r2))
        elif kind == 'd':
            # Delete lines l1..l2 of a, after line r1 of b.
            changes.append((l1 - 1, l2, r1, r1))
        else:
            changes.append((l1 - 1, l2, r1 - 1, r2))
    return changes


def condition(where, platforms):
    parts = []
    for o in OSES:
        arches = [a for a in ARCHES if (o, a) in where]
        if not arches:
            continue
        if all((o, a) in where for a in ARCHES if (o, a) in platforms):
            parts.append(f'defined({OS_MACROS[o]})')
        else:
            parts += [f'(defined({OS_MACROS[o]}) && defined({ARCH_MACROS[a]}))' for a in arches]
    return ' || '.join(parts)


def check(merged, platforms, sources):
    """Checks that the lines for each platform can be taken back out of the
    merged C."""
    lines = merged.splitlines(keepends=True)
    for p in platforms:
        o, a = p
        out = []
        keep = True
        for line in lines:
            if line.endswith(MARK + '\n'):
                if line.startswith('#if '):
                    keep = evaluate(line[4:-len(MARK) - 2], o, a)
                else:
                    keep = True
                continue
            if keep:
                out.append(line)
        if out != sources[p]:
            sys.exit(f'the merged C is different to the C for {o} {a}')


def evaluate(expression, os_, arch):
    expression = expression.replace(f'defined({OS_MACROS[os_]})', 'True')
    expression = expression.replace(f'defined({ARCH_MACROS[arch]})', 'True')
    expression = re.sub(r'defined\(\w+\)', 'False', expression)
    expression = expression.replace('||', 'or').replace('&&', 'and')
    return eval(expression)


if __name__ == '__main__':
    main()
